def _normalize_ciphers(ciphers):
    """Convert accepted cipher inputs to the string format used by OpenSSL."""
    if isinstance(ciphers, string_types):
        cipher_string = ciphers
    elif isinstance(ciphers, list) and all(isinstance(cipher, string_types) for cipher in ciphers):
        cipher_string = ':'.join(ciphers)
    else:
        raise ValueError('ciphers must be an OpenSSL cipher string or a list of strings')

    if not cipher_string.strip():
        raise ValueError('ciphers must contain at least one cipher')

    return cipher_string


